insert into public.avis (auteurs, role_fr, role_en, categorie, texte_fr, texte_en, citation_fr, citation_en, source, publie, ordre, emplacements) values
('Mathilde', null, null, 'mariage', 'Nous avons passé une soirée inoubliable avec une programmation musicale acclamée par nos invités ! Grande réactivité, professionnalisme, écoute attentive, flexibilité totale pour modeler une cérémonie sur mesure… Bref nous ne pouvons que recommander les services de Cédric.', 'We had an unforgettable evening with music our guests loved! Very responsive, professional, attentive, and completely flexible in shaping a tailor-made ceremony… In short, we can only recommend Cédric''s services.', null, null, 'site', true, 10, '{}'),
('Clémence & Nicolas', null, null, 'mariage', 'Spice Events a animé notre mariage : cérémonie religieuse à l’église puis dîner et soirée. L’équipe a totalement su répondre à nos attentes avec beaucoup de professionnalisme. Notre soirée de mariage était un succès et s’est terminée à 5H du matin avec encore une vingtaine de personnes sur le dancefloor. Nous vous recommandons Cédric et son équipe les yeux fermés.', 'Spice Events looked after our wedding: a religious ceremony at the church, followed by dinner and the party. The team met all our expectations with great professionalism. Our wedding party was a success and finished at 5 am with around twenty people still on the dance floor. We recommend Cédric and his team without hesitation.', null, null, 'site', true, 20, '{}'),
('Charlotte & Thibault', null, null, 'mariage', 'Cédric a été absolument extraordinaire pour notre mariage. Dès le moment où nous l''avons contacté, il a fait tout son possible pour comprendre ce que nous voulions pour notre journée spéciale. Notre journée était absolument parfaite avec le son, l''éclairage, la musique, la projection vidéo, le streaming en direct et un DJ incroyable. Tout s''est déroulé en douceur et nous sommes très reconnaissants de tout ce qu''il a fait pour nous. La perfection absolue ! Merci beaucoup à Cédric et à l''équipe de Spice Events !', 'Cédric was absolutely extraordinary for our wedding. From the moment we contacted him, he did everything he could to understand what we wanted for our special day. Our day was absolutely perfect, with the sound, the lighting, the music, the video projection, the live streaming and an incredible DJ. Everything went smoothly and we are so grateful for everything he did for us. Absolute perfection! Many thanks to Cédric and the Spice Events team!', null, null, 'site', true, 30, '{}'),
('Marine & Gaëtan', null, null, 'mariage', 'Nous avons fait appel à Spice Events pour notre mariage et nous ne regrettons pas notre choix. Des échanges professionnels et réactifs en amont nous ont permis de nous concentrer sur d''autres préparatifs. Le personnel à l''écoute a su adapter avec brio sa prestation pour satisfaire nos envies (choix des musiques, déroulé de la soirée, horaires, tarifs...), logistique parfaite de l''installation accompagnée d''un matériel de très haute qualité pour des tarifs vraiment concurrentiels. Le DJ à mis le feu sur la piste de danse tout en étant présent à bon escient lors des animations de la soirée. Merci à Spice Events d''avoir transformé cette belle journée en un jour magique et inoubliable !', 'We booked Spice Events for our wedding and we don''t regret our choice. Professional, responsive exchanges beforehand allowed us to focus on other preparations. The attentive staff brilliantly adapted their service to what we wanted (choice of music, running order of the evening, timings, prices...), with flawless logistics for the set-up and very high-quality equipment at really competitive prices. The DJ set the dance floor on fire while being there at just the right moments for the evening''s entertainment. Thank you, Spice Events, for turning this beautiful day into a magical, unforgettable one!', null, null, 'site', true, 40, '{mariages}'),
('Beth & Liam', null, null, 'mariage', 'Je recommande absolument Spice Events pour votre événement ! Cédric s''est occupé de tout pour notre mariage : DJ, musique de la cérémonie et du cocktail, photobooth, éclairage...tout était parfait ! Le photobooth a eu un immense succès auprès de nos invités, et la musique était impeccable, même avec les quelques demandes de dernnières minutes. Rien à redire, ils ont fait un travail exceptionnel !', 'I absolutely recommend Spice Events for your event! Cédric took care of everything for our wedding: DJ, music for the ceremony and the drinks reception, photo booth, lighting... everything was perfect! The photo booth was a huge hit with our guests, and the music was spot on, even with a few last-minute requests. Nothing to fault — they did an exceptional job!', 'Le photobooth a eu un immense succès auprès de nos invités, et la musique était impeccable, même avec les quelques demandes de dernnières minutes. Rien à redire, ils ont fait un travail exceptionnel !', 'The photo booth was a huge hit with our guests, and the music was spot on, even with a few last-minute requests. Nothing to fault — they did an exceptional job!', 'site', true, 50, '{option:photobooth}'),
('Pierre & Nina', null, null, 'mariage', 'Cédric s’est occupé de toute la partie musicale et festive de notre mariage — de la cérémonie jusqu’à la piste de danse — et tout a été absolument parfait ! Très professionnel, à l’écoute et toujours de bon conseil, il a su comprendre nos envies et créer une ambiance incroyable du début à la fin. Nous avons eu plusieurs échanges avec lui avant le jour J, ce qui nous a beaucoup aidés à bien préparer les moments clés de la soirée. Sa flexibilité et son sens de l’organisation ont fait toute la différence : la piste de danse n’a jamais désempli ! Les options proposées par Spice Events, comme le photobooth, les étincelles froides ou encore la mise en lumière, ont apporté cette touche magique qui a rendu notre mariage unique. Le matériel était de grande qualité, et la décoration, parfaitement adaptée à l’ambiance que nous souhaitions. Nous sommes ravis d’avoir fait appel à Spice Events et recommandons Cédric les yeux fermés à tous ceux qui veulent une soirée réussie, festive et inoubliable. Merci encore pour tout !', 'Cédric took care of all the music and party side of our wedding — from the ceremony right through to the dance floor — and everything was absolutely perfect! Very professional, attentive and always full of good advice, he understood what we wanted and created an incredible atmosphere from start to finish. We had several conversations with him before the big day, which really helped us prepare the key moments of the evening. His flexibility and organisation made all the difference: the dance floor was never empty! The extras offered by Spice Events, such as the photo booth, the cold sparks and the lighting, added that magical touch that made our wedding unique. The equipment was top quality, and the decoration perfectly suited to the atmosphere we wanted. We''re delighted we chose Spice Events and recommend Cédric without hesitation to anyone who wants a successful, festive and unforgettable party. Thank you again for everything!', null, null, 'site', true, 60, '{accueil_grand}'),
('Maxime & Sauvanne', null, null, 'mariage', 'Quel mariage ! Ça n’aurait jamais été le même sans Cedric et son équipe. Merci beaucoup car quand l''on pense à un DJ pour son mariage on devrait tous penser à Cedric qui est d''une gentilesse rare ! Il a été à l’écoute, professionnel, il s’est adapté, à su parfaitement mettre l’ambiance et à respecter nos goûts musicaux, bref un pro comme on n’ose l’espérer. Il connais sont métier ! Merci à lui pour avoir animer (enflammer) la piste de danse tout du long. Nos invités ont été plus que ravies. Mille mercis !!', 'What a wedding! It would never have been the same without Cédric and his team. Thank you so much — when you think of a DJ for your wedding, Cédric is the one everyone should think of: he is exceptionally kind! He listened, he was professional, he adapted, he created the perfect atmosphere and respected our musical tastes — in short, a true pro beyond anything you''d dare hope for. He knows his job! Thank you to him for keeping the dance floor going (on fire!) all night long. Our guests were more than delighted. A thousand thanks!!', null, null, 'site', true, 70, '{}'),
('Charlotte & David', null, null, 'mariage', 'Professionnel, discret, gentil... mais surtout une cérémonie laïque parfaitement gérée et une ambiance de folie tout au long de la soirée !! C''est donc les yeux fermés que je vous recommande Spice Events ! Cédric⁩ & Stéphane, milles mercis pour avoir géré toute la sonorisation de notre mariage, et pour cette soirée dont on se rappellera toute notre vie ! C’était la folie, tout le monde a dansé jusqu’à épuisement je crois, les plus vieux comme les plus jeunes, et on s’est éclatés du début à la fin sans aucune fausse note. Et pourtant je pense qu’on était des mariés difficiles puisque Monsieur est lui même ancien DJ de mariage et a été très regardant sur cet aspect ! C''est donc les yeux fermés que nous recommandons Cédric et Spice Events.', 'Professional, discreet, kind... but above all a perfectly managed celebrant-led ceremony and an amazing atmosphere all evening long!! So I recommend Spice Events without hesitation! Cédric & Stéphane, a thousand thanks for handling all the sound for our wedding, and for a party we''ll remember for the rest of our lives! It was wild — I think everyone danced until they dropped, young and old alike, and we had a blast from start to finish without a single wrong note. And yet I think we were demanding clients, since my husband is a former wedding DJ himself and was very particular about this! So we recommend Cédric and Spice Events without hesitation.', null, null, 'site', true, 80, '{accueil}'),
('Harold & David', null, null, 'mariage', 'La prestation de Cédric est largement allé au-delà de celle d''un très bon DJ. Il nous a vraiment accompagné tout au long de la préparation de notre mariage, jusqu''au jour J. Son organisation, ses questions, ses conseils ont été extrêmement précieux pour nous aider à concocter un mariage d''exception. Le jour J, tout s''est déroulé parfaitement. Tout a bien été anticipé et la logistique importante ne s''est pas faite sentir. Cédric et Stéphane ont sublimé notre espace de soirée et ont permis que les ambiances scéniques de la cérémonie jusqu''au bout de la nuit soient exceptionnelles. Au-delà de la qualité de leur travail, ils ont aussi su être présents et sont restés extrêmement sympathiques. De nombreux invités nous en ont fait la remarque et cela a vraiment contribué à l''ambiance de notre mariage.', 'Cédric''s service went far beyond that of a very good DJ. He really supported us throughout the planning of our wedding, right up to the big day. His organisation, his questions and his advice were extremely valuable in helping us put together an exceptional wedding. On the day, everything went perfectly. Everything had been anticipated and the considerable logistics went unnoticed. Cédric and Stéphane transformed our party space and made the staging and atmosphere exceptional, from the ceremony right through the night. Beyond the quality of their work, they were always there for us and remained extremely friendly. Many guests mentioned it to us, and it really added to the atmosphere of our wedding.', null, null, 'site', true, 90, '{mariages_grand}'),
('Pascal & Abigaïl', null, null, 'mariage', 'Si vous souhaitez avoir une bonne ambiance lors de votre mariage choisissez Spice Events. Tant sur le plan musicale (respect des styles musicaux, bonnes transitions), que sur la bonne ambiance apportée lors des animations (bar à vinyle, jeux des mariés). En plus de leur prestation musicale, ils proposent des lumières d''ambiance ainsi qu''un photobooth. Le petit plus a été lors de la cérémonie laïque où son sens du timing a permis de susciter l''émotion à l''ensemble de nos invités en créant une atmosphère romantique. Ce joyeux mélange à contribué à créer un mariage parfait.', 'If you want a great atmosphere at your wedding, choose Spice Events. Both musically (respecting the styles of music, good transitions) and in the great atmosphere they brought to the entertainment (vinyl bar, newlyweds'' games). As well as the music, they offer mood lighting and a photo booth. The real bonus was the celebrant-led ceremony, where his sense of timing moved all our guests by creating a romantic atmosphere. This joyful mix helped create a perfect wedding.', 'Le petit plus a été lors de la cérémonie laïque où son sens du timing a permis de susciter l''émotion à l''ensemble de nos invités en créant une atmosphère romantique. Ce joyeux mélange à contribué à créer un mariage parfait.', 'The real bonus was the celebrant-led ceremony, where his sense of timing moved all our guests by creating a romantic atmosphere. This joyful mix helped create a perfect wedding.', 'site', true, 100, '{mariages,option:sonorisation-ceremonie-laique}'),
('Aaron & Niamha', null, null, 'mariage', 'Nous sommes ravis du service fourni par Cédric de Spice Events ! Dès les préparatifs, il s’est montré très à l’écoute, disponible et professionnel. Nous avons eu plusieurs échanges avant le mariage pour discuter de l’organisation, du déroulé de la journée et du choix des musiques, et tout s’est déroulé à la perfection le jour J. Cédric est fiable, sympathique et très accessible. Le système de sonorisation était incroyable, tout comme les jeux de lumières et les effets spéciaux qui ont sublimé l’ambiance. La sélection musicale était parfaite : il a diffusé toutes nos chansons préférées et évité celles que nous ne voulions pas entendre. Voyant à quel point nos invités s’amusaient, il a même proposé de prolonger la soirée sur le moment — ce qui nous a permis de continuer la fête encore plus longtemps ! Nous ne le remercierons jamais assez. Nous recommandons Spice Events les yeux fermés !', 'We are delighted with the service provided by Cédric at Spice Events! From the start of the preparations, he was very attentive, available and professional. We had several conversations before the wedding about the organisation, the running order of the day and the choice of music, and everything went perfectly on the day. Cédric is reliable, friendly and very approachable. The sound system was incredible, as were the lighting and special effects, which made the atmosphere even better. The music selection was perfect: he played all our favourite songs and avoided the ones we didn''t want to hear. Seeing how much our guests were enjoying themselves, he even offered to extend the evening on the spot — which meant we could keep the party going even longer! We can''t thank him enough. We recommend Spice Events without hesitation!', null, null, 'site', true, 110, '{mariages}'),
('Frédéric & Selda', null, null, 'mariage', 'Cédric est au top et très pro ! Un rendez vous physique pour un premier échange, et plusieurs rendez vous en visio par la suite pour avancer sur notre projet ensemble. Très à l’écoute, il nous a orienté au mieux afin de faire de notre journée un succès ! Avec son anticipation et sa préparation, aucun loupé ! Une de ses qualités est qu’il est très observateur et attentif à ce qui se passe sur la piste, il a su mettre les bons morceaux au bon moment afin de nous faire danser jusqu’à 5h ! On recommande vivement Cédric !', 'Cédric is brilliant and very professional! A face-to-face meeting to start with, then several video calls to move our plans forward together. Very attentive, he guided us so that our day would be a success! Thanks to his foresight and preparation, nothing went wrong! One of his strengths is that he''s very observant and attentive to what''s happening on the dance floor: he played the right songs at the right time and kept us dancing until 5 am! We highly recommend Cédric!', null, null, 'site', true, 120, '{accueil}'),
('Clémentine & Kévin', null, null, 'mariage', 'Mémorable ! Notre mariage était magique et inoubliable. Cédric a participé à cette réussite car il a su créer l''atmosphère musicale que nous attendions. De la cérémonie laïque rétro au dance floor électro en passant par le blindt test integenerationnel, il a su emporter tous nos invités au fil de la journée. Haut les coeurs ! Foncez! Les rdv de préparation étaient pros et le rendu des photos très rapide. J''oubliais.... Notre ouverture de bal était digne d''un Danse Avec Les Stars ! Les jeux de lumières étaient parfaits ! Merci Spice Events pour tout ça !', 'Memorable! Our wedding was magical and unforgettable. Cédric played his part in that success, because he created exactly the musical atmosphere we were hoping for. From the retro celebrant-led ceremony to the electro dance floor, by way of the multi-generational blind test, he carried all our guests along throughout the day. Take heart! Go for it! The planning meetings were professional and the photos came through very quickly. I almost forgot... Our first dance was worthy of Strictly Come Dancing! The lighting was perfect! Thank you, Spice Events, for all of it!', 'Notre ouverture de bal était digne d''un Danse Avec Les Stars ! Les jeux de lumières étaient parfaits ! Merci Spice Events pour tout ça !', 'Our first dance was worthy of Strictly Come Dancing! The lighting was perfect! Thank you, Spice Events, for all of it!', 'site', true, 130, '{accueil,option:ouverture-de-bal}'),
('Juliette', 'Responsable communication', 'Communications manager', 'evenement', 'Un suivi complet et humain : conseils sur les moments clés, coordination avec les prestataires, et présence rassurante le jour J. L’équipe a rendu notre événement simple à gérer et vraiment agréable.', 'Complete, personal support: advice on the key moments, coordination with the suppliers, and a reassuring presence on the day. The team made our event easy to manage and genuinely enjoyable.', null, null, 'site', true, 140, '{}'),
('Lucas R.', 'Chef de projet événementiel', 'Event project manager', 'evenement', 'L’accompagnement proposé par Spice Events a été un vrai atout pour notre soirée corporate. De la préparation à la coordination le jour J, tout a été clair, précis et professionnel. Nous avons pu nous concentrer sur nos invités et notre message.', 'The support provided by Spice Events was a real asset for our corporate evening. From the preparation to the coordination on the day, everything was clear, precise and professional. We were able to focus on our guests and our message.', null, null, 'site', true, 150, '{}'),
('Camille & Théo', null, null, 'mariage', 'Dès notre premier rendez-vous, nous avons senti que tout serait sous contrôle. L’équipe Spice Events a su comprendre nos envies et nous guider pour chaque moment fort de notre mariage. Un accompagnement rassurant et professionnel du début à la fin.', 'From our very first meeting, we felt that everything would be under control. The Spice Events team understood what we wanted and guided us through every highlight of our wedding. Reassuring, professional support from start to finish.', null, null, 'site', true, 160, '{}'),
('Léa & Floris', null, null, 'mariage', 'Le suivi en amont était impeccable. Entre le questionnaire, les échanges réguliers et les conseils pour la musique et les animations, nous avons eu l’impression d’être guidés par des experts. Tout était parfaitement orchestré le jour J.', 'The support beforehand was impeccable. Between the questionnaire, the regular conversations and the advice on music and entertainment, we felt we were being guided by experts. Everything was perfectly orchestrated on the day.', null, null, 'site', true, 170, '{}'),
('Sophie', 'Responsable événementiel d''entreprise', 'Corporate events manager', 'evenement', 'Spice Events nous a accompagnés pas à pas pour notre séminaire annuel. Les conseils personnalisés et la coordination avec tous nos prestataires ont rendu l’organisation fluide et sans stress. Une équipe vraiment à l’écoute.', 'Spice Events supported us step by step for our annual seminar. Their personalised advice and coordination with all our suppliers made the organisation smooth and stress-free. A team that really listens.', null, null, 'site', true, 180, '{}'),
('Julie H.', 'Responsable sponsoring', 'Sponsorship manager', 'evenement', 'Cédric et son équipe ont transformé notre événement en un véritable succès. La musique, les lumières et l’ambiance ont été parfaitement adaptées à nos invités. Tout le monde a adoré !', 'Cédric and his team turned our event into a real success. The music, the lighting and the atmosphere were perfectly suited to our guests. Everyone loved it!', null, null, 'site', true, 190, '{}'),
('Frédéric A.', 'Chargé de production', 'Production manager', 'evenement', 'Nous avions besoin d’une animation professionnelle. Cédric a su créer une ambiance élégante et festive à la fois, tout en respectant notre image. Bravo !', 'We needed professional entertainment. Cédric created an atmosphere that was both elegant and festive, while staying true to our image. Well done!', null, null, 'site', true, 200, '{}'),
('Claire D.', 'Cheffe de projet événementiel', 'Event project manager', 'evenement', 'Grâce à leur accompagnement en amont, chaque moment fort de notre événement a été mis en valeur. La musique et l’éclairage ont parfaitement rythmé la journée.', 'Thanks to their support beforehand, every highlight of our event was showcased. The music and lighting set the perfect rhythm for the day.', null, null, 'site', true, 210, '{}'),
('Thomas H.', 'Directeur communication', 'Communications director', 'evenement', 'Une équipe à l’écoute, professionnelle et passionnée. Tout a été parfaitement orchestré, de la mise en lumière à la sélection musicale. L’ambiance était au rendez-vous du début à la fin !', 'A team that listens, professional and passionate. Everything was perfectly orchestrated, from the lighting to the music selection. The atmosphere was there from start to finish!', null, null, 'site', true, 220, '{}'),
('Marc L.', 'Directeur marketing', 'Marketing director', 'evenement', 'Nous avons fait appel à Spice Events pour notre soirée annuelle. L’organisation était impeccable, le matériel de qualité et l’équipe très réactive. Nos collaborateurs en parlent encore !', 'We called on Spice Events for our annual party. The organisation was impeccable, the equipment top quality and the team very responsive. Our staff are still talking about it!', null, null, 'site', true, 230, '{}'),
('Lucas P.', 'Responsable RH', 'HR manager', 'evenement', 'La soirée a été incroyable ! La playlist, les animations et la coordination avec les prestataires ont rendu l’événement fluide et mémorable pour tous nos invités', 'The evening was incredible! The playlist, the entertainment and the coordination with the suppliers made the event smooth and memorable for all our guests.', null, null, 'site', true, 240, '{}'),
('Lucas & Marie', null, null, 'mariage', 'DJ au top ! Nous recommandons vivement Spice Event pour animer vos événements et plus particulièrement pour votre mariage. Très bon matériel de sonorisation et de lumière, le rendu était magnifique. Spice Event a su faire danser toutes les générations jusqu''au bout de la nuit ! Un grand merci pour tout.', 'Brilliant DJ! We highly recommend Spice Events for your events, and especially for your wedding. Very good sound and lighting equipment — the result was magnificent. Spice Events got every generation dancing until the end of the night! A big thank you for everything.', null, null, 'site', true, 250, '{}'),
('Claire & Lucile', null, null, 'mariage', 'Super prestation. Super ambiance lumineuse et sonore grâce à Cédric ! Même un changement de musique au dernier moment a été assuré sans sourciller. Merci ! On recommande plutôt deux fois qu''une !', 'Great service. A wonderful lighting and sound atmosphere thanks to Cédric! Even a last-minute change of music was handled without batting an eyelid. Thank you! We''d recommend them twice over!', null, null, 'site', true, 260, '{}'),
('Emmanuelle & Georges', null, null, 'mariage', 'Ambiance au top ! 7 mars 2020, Domaine du Parc à Pontcarré, avec une centaine de proches à l''occasion de notre mariage : ce fut une fabuleuse soirée orchestrée de main de maître par Cédric, aux platines et à la lumière. Il a suffit d''une discussion en amont pour qu''il comprenne nos attentes, et la fête fut donc parfaite.', 'A brilliant atmosphere! 7 March 2020, Domaine du Parc in Pontcarré, with around a hundred of our loved ones for our wedding: it was a fabulous evening, masterfully orchestrated by Cédric on the decks and the lighting. One conversation beforehand was all it took for him to understand what we wanted, and so the party was perfect.', null, null, 'site', true, 270, '{}'),
('Nathalie & Alexis', null, null, 'mariage', 'Mille mercis ! Spice Events a été largement à la hauteur de nos attentes et plus encore. Cédric Allard a su comprendre nos contraintes liées à un emploi du temps très chargé et nous a attribué Aurélien qui a su faire preuve de professionnalisme avec le sourire. A la fois discret et s''adaptant à chaque moment de la soirée il est top ! Un grand merci pour cette soirée où notre seule envie était de faire passer un bon moment à nos invités et profiter pleinement.', 'A thousand thanks! Spice Events more than lived up to our expectations. Cédric Allard understood the constraints of our very busy schedule and assigned us Aurélien, who was professional and always smiling. Discreet and adapting to every moment of the evening, he''s brilliant! A huge thank you for this evening, when all we wanted was for our guests to have a great time and to enjoy it to the full.', null, null, 'site', true, 280, '{}'),
('Alice & Thomas', null, null, 'mariage', 'Prestations parfaites par un prestataire de confiance Nous avons eu la joie de faire appel à Spice Events pour notre mariage. Nous apprécions énormément la musique et il était inconcevable qu''elle soit relayée au second plan. Nos contacts ont été supers, de notre 1er échange jusqu''au jour J ! Cédric & Aurélien ont parfaitement cernés nos goûts : quel plaisir de se laisser porter par la musique sans qu''il y ait le moindre impair ❤️ Au delà des choix musicaux & de la soirée (son + lumières), nous avions aussi confié à Spice Events la sono de la cérémonie laïque qui avait lieu en plein air. Un sans faute là aussi 👌🏼 Une entreprise de confiance. Spice Event a été plus qu''au top pour notre mariage. Super disponible avant pour préparer avec nous l''ambiance musicale, le DJ a pris beaucoup de temps pour tout préparer et une fois le jour J tout s''est très bien passé. Nous avons été très satisfaits et nos invités aussi ! Leur matériel (sono + lumière) nous a aussi bien sauvé la vie car celui du lieu rencontrait un problème. Un grand merci à eux que je recommande absolument.', 'Perfect service from a supplier you can trust. We were delighted to book Spice Events for our wedding. We love music and it was unthinkable for it to take a back seat. Our contact was great, from our first conversation right up to the big day! Cédric & Aurélien understood our tastes perfectly: what a pleasure to let ourselves be carried by the music without a single misstep ❤️ Beyond the music and the party (sound + lighting), we had also entrusted Spice Events with the sound for our outdoor celebrant-led ceremony. Flawless there too 👌🏼 A company you can trust. Spice Events were more than brilliant for our wedding. Very available beforehand to prepare the musical atmosphere with us, the DJ took a lot of time to get everything ready, and on the day everything went very well. We were very satisfied, and so were our guests! Their equipment (sound + lighting) also saved the day, because the venue''s own was having a problem. A big thank you to them — I absolutely recommend them.', null, null, 'site', true, 290, '{}'),
('Sébastien & Guylaine', null, null, 'mariage', 'Une équipe au top ! Du matériel au top ! Quand vous avez l''équipe de sonorisation et de lumière qui fait des bons derrière les platines au son de rythmes endiablés vous savez que vous avez fait appel à la bonne équipe ! Merci ! Une ambiance de folie et une équipe très « professionnelle » ! L''équipe a su s''adapter aux invités d''âges pourtant très différents. Bravo !', 'A brilliant team! Brilliant equipment! When the sound and lighting team are jumping up and down behind the decks to wild rhythms, you know you''ve booked the right team! Thank you! An amazing atmosphere and a very “professional” team! The team adapted to guests of very different ages. Well done!', null, null, 'site', true, 300, '{}'),
('Marie Ange & Romain', null, null, 'mariage', 'Soirée extraordinaire. Nous avons réservé avec Spice Events pour notre mariage et en sommes ravis ! Tout était parfait, les éclairages et effets, la musique, même la gestion de la sonorisation pour notre cérémonie laïque. Pour la soirée, la piste a toujours été remplie, ça montre vraiment le talent du DJ. On avait aussi loué les supers chaises Napoléon qui ont fait un très bel effet, ainsi que la borne photo qui a été un très gros succès et une réelle animation pour les invités tout au long de la soirée. Merci à toute l''équipe, c''était formidable ! Merci pour ce magnifique mariage, autant pour la cérémonie laïque que pour la soirée, c''était juste incroyable ! Les éclairages étaient extraordinaires et la musique a fait l''unanimité. Je recommande à 1000%', 'An extraordinary evening. We booked Spice Events for our wedding and we''re delighted! Everything was perfect: the lighting and effects, the music, even the sound for our celebrant-led ceremony. During the party, the dance floor was always full, which really shows the DJ''s talent. We had also hired the gorgeous Napoleon chairs, which looked stunning, and the photo booth, which was a huge hit and real entertainment for the guests all evening. Thank you to the whole team, it was wonderful! Thank you for this beautiful wedding, both the celebrant-led ceremony and the party — it was simply incredible! The lighting was extraordinary and the music won everyone over. I recommend them 1000%', null, null, 'site', true, 310, '{}'),
('Camille & Alexander', null, null, 'mariage', 'Super prestation ! Cédric a su nous trouver un DJ qui correspondait parfaitement à nos attentes. Aurélien est resté discret quand il le fallait, puis a su mettre l''ambiance sur la piste de danse pendant la soirée ! Au top, je recommande vivement les services de Spice Event', 'Great service! Cédric found us a DJ who matched our expectations perfectly. Aurélien stayed discreet when needed, then got the dance floor going during the party! Brilliant — I highly recommend Spice Events.', null, null, 'site', true, 320, '{}'),
('Léa & Floris', null, null, 'mariage', 'Un prestataire accessible, qui s''adapte à toutes les situations avec professionnalisme. Le bar a vinyle à été un véritable succès. De la cérémonie à la fin de soirée la sono a été gérée à merveille. Un professionnel de qualité, autant par son matériel que son travail. Il arrive à s''adapter rapidement aux demandes de chacun. Nous avions pris en sus le bar à vinyl, cela a beaucoup plu et a permis d''ambiancé dès le vin d''honneur. Nous sommes passé par lui également pour la location de tables et de chaises. Et autant qu''un mauvais DJ peut gâcher un mariage. Et là c''est en partie grâce à lui que le nôtre a été extraordinaire.', 'An approachable supplier who adapts to every situation with professionalism. The vinyl bar was a real hit. From the ceremony to the end of the evening, the sound was handled beautifully. A quality professional, in both his equipment and his work. He adapts quickly to everyone''s requests. We had added the vinyl bar, which was very popular and got the atmosphere going from the drinks reception onwards. We also went through him to hire tables and chairs. A bad DJ can ruin a wedding — and here, it''s partly thanks to him that ours was extraordinary.', 'Le bar a vinyle à été un véritable succès. De la cérémonie à la fin de soirée la sono a été gérée à merveille. Un professionnel de qualité, autant par son matériel que son travail. Il arrive à s''adapter rapidement aux demandes de chacun.', 'The vinyl bar was a real hit. From the ceremony to the end of the evening, the sound was handled beautifully. A quality professional, in both his equipment and his work. He adapts quickly to everyone''s requests.', 'site', true, 330, '{option:bar-a-vinyles}'),
('Justine & Victor', null, null, 'mariage', 'Nous sommes ravis de la prestation de Spice Events pour notre mariage le 23 juillet dernier qui a largement contribué à rendre ce jour exceptionnel. La mise en place lumière a sublimé les lieux .L''équipe été au petit soin pour tout les détails animations et musique , ainsi que leur contribution dans les nombreuses surprises de nos proches et témoins . Sans parler du dj qui a réussi un mélange parfait entre musique brésilienne et française , résultat : une ambiance de folie, une piste qui n''a pas désemplie jusqu''à 7h du matin , des convives et des mariés ravis! Un grand merci à Cedric et son équipe que nous recommandons chaudement !', 'We are delighted with Spice Events'' service for our wedding last 23 July, which went a long way towards making the day exceptional. The lighting set-up made the venue look stunning. The team took care of every detail of the entertainment and music, and helped with the many surprises from our loved ones and witnesses. Not to mention the DJ, who achieved a perfect blend of Brazilian and French music — the result: an amazing atmosphere, a dance floor that stayed full until 7 am, and delighted guests and newlyweds! A big thank you to Cédric and his team, whom we warmly recommend!', null, null, 'site', true, 340, '{}'),
('Flore & Jeremy', null, null, 'mariage', 'Excellente prestation ! Je recommande fortement. Notre mariage n''aurait jamais été aussi réussi sans le professionnalisme apporté par Cédric et son équipe lors de cet événement ! Merci encore énormément à Benjamin pour cette folle soirée finie sous la pluie mais dans la plus folle ambiance ! A très bientôt.', 'Excellent service! I highly recommend them. Our wedding would never have been such a success without the professionalism Cédric and his team brought to it! Huge thanks again to Benjamin for a wild evening that ended in the rain, but with the craziest atmosphere! See you very soon.', null, null, 'site', true, 350, '{}'),
('Pauline & Anton', null, null, 'mariage', 'Merci Spice Event ! Nous avons fait confiance à Cédric et Aurélien (le DJ) pour l''animation de la soirée de notre mariage et nous ne pouvions pas rêver mieux ! L''organisation était parfaite et l''ambiance garantie, ils ont tous les deux su écouter nos besoins et envies. La soirée a été parfaite !! Encore un grand merci pour le professionnalisme.', 'Thank you, Spice Events! We trusted Cédric and Aurélien (the DJ) with the entertainment for our wedding party and we couldn''t have dreamed of better! The organisation was perfect and the atmosphere guaranteed; they both listened to what we needed and wanted. The evening was perfect!! Thank you again for your professionalism.', null, null, 'site', true, 360, '{}'),
('Azline & Edouard', null, null, 'mariage', 'Inoubliable !! Nous avons fait appel à Cédric et ses équipes pour l''animation de notre mariage, quelle magnifique soirée ! Une équipe de professionnels à votre écoute et à qui vous pouvez faire confiance les yeux fermés. Les dispositifs d''éclairage proposés ont permis la mise en valeur de notre salle de réception, un travail de qualité pour une ambiance chaleureuse. Ils ont su faire danser toutes les générations jusqu''au petit matin, il y en avait pour tous les goûts, une vraie réussite ! N''hésitez pas à les solliciter pour vos réceptions, vous ne serez pas déçus. Un grand merci !', 'Unforgettable!! We booked Cédric and his teams for the entertainment at our wedding — what a magnificent evening! A team of professionals who listen to you and whom you can trust completely. The lighting they suggested showed off our reception room beautifully: quality work for a warm atmosphere. They got every generation dancing until the early hours, there was something for every taste — a real success! Don''t hesitate to call on them for your receptions, you won''t be disappointed. A big thank you!', null, null, 'site', true, 370, '{mariages}'),
('Constance & Mathieu', null, null, 'mariage', 'Parfait ! Cédric a été super au niveau pro, rdv, timing, services en extra. Il a fait dans TOUT le monde, nous avons eu un super feedback de tous nos invités, plus agés comme plus jeunes. Les jeux de lumières étaient tops également. Merci beaucoup Cédric pour ton professionnalisme. Nous vous le recommandons les yeux fermés. Elégance et maitrise de tout de A à Z.', 'Perfect! Cédric was great on every front: professionalism, meetings, timing, extra services. He got EVERYONE dancing, and we had great feedback from all our guests, older and younger alike. The lighting was brilliant too. Thank you so much, Cédric, for your professionalism. We recommend him without hesitation. Elegance and complete mastery from A to Z.', null, null, 'site', true, 380, '{}'),
('David & Elodie', null, null, 'mariage', 'Nous avons confié toute la sonorisation de notre mariage à Cédric qui a impeccablement tout géré! La cérémonie laïque, le cocktail, la soirée et également tous les jeux de lumières. Il a su s’adapter aux contraintes du lieu pour rendre ce moment merveilleux. Nous avons échanger sur nos envies, tout à été respecté, les convives étaient ravis, tout le monde a dansé de 7 à 77 ans! Je recommande vivement ce prestataire, vous pouvez y aller les yeux fermés! Cédric est un « vrai » pro, il a réussit à être présent en toute discrétion, et a su répondre à nos attentes qui n’etaient des moindres pour notre mariage! Cédric à géré la sonorisation complète ainsi que tout l éclairage! Je recommande vivement ce prestataire. PS: et le Photo Booth aussi!! Bref il gère !', 'We entrusted all the sound for our wedding to Cédric, who handled everything impeccably! The celebrant-led ceremony, the drinks reception, the party and all the lighting too. He adapted to the constraints of the venue to make it a wonderful moment. We talked about what we wanted, everything was respected, the guests were delighted, and everyone danced, from 7 to 77! I highly recommend this supplier — you can book him with your eyes closed! Cédric is a “real” pro: he managed to be there with complete discretion, and met our expectations, which were far from modest for our wedding! Cédric handled the complete sound system as well as all the lighting! I highly recommend this supplier. PS: and the photo booth too!! In short, he''s got it all covered!', null, null, 'site', true, 390, '{mariages}'),
('Marie & Quentin', null, null, 'mariage', 'Marie : Parfait !! 5/5 Merci Cedric pour ton accompagnement, tes bons conseils et ton professionnalisme le jour j ! Nous avons eu pleins de compliments sur la soirée dansante et l’ambiance de notre mariage ! Cédric a été vraiment au top ! Que ce soit sur le choix de ses musiques, l’ambiance, la gestion du mix pour l’ouverture de bal tout était parfait ! Il a de très bons conseils et de bonnes idées ! Installation parfaite. Merci encore !', 'Marie: Perfect!! 5/5 Thank you, Cédric, for your support, your good advice and your professionalism on the day! We got lots of compliments on the dancing and the atmosphere at our wedding! Cédric was truly brilliant! Whether it was his choice of music, the atmosphere or the mix for our first dance, everything was perfect! He gives great advice and has great ideas! Flawless set-up. Thank you again!', null, null, 'site', true, 400, '{}'),
('Coralie & Benjamin', null, null, 'mariage', 'Cédric a su être l''écoute de nos demandes, s''adapter à notre lieu (et ses différentes salles) et à l''univers de notre mariage tout en étant très disponible pendant la préparation. Du début à la fin de la partie dansante, la piste n''a pas désempli, nous étions encore une dizaine à 5h du matin !', 'Cédric listened to our requests and adapted to our venue (and its different rooms) and to the theme of our wedding, while being very available during the preparations. From the beginning to the end of the dancing, the dance floor never emptied — there were still about ten of us at 5 am!', null, null, 'site', true, 410, '{option:sonorisation-deportee}'),
('Quentin & Pauline', null, null, 'mariage', 'Cédric a été top du début à la fin ! Au-delà de mettre l’ambiance et faire danser tout le monde, c’est une personne disponible, humaine, qui fait son travail avec passion — et ça se ressent vraiment. Un vrai plaisir de l’avoir eu à nos côtés pour notre mariage. Merci encore, on recommande les yeux fermés ! Petit plus : éclairages et projecteurs au top, le rendu est génial. On recommande à 100 % !', 'Cédric was brilliant from start to finish! Beyond creating the atmosphere and getting everyone dancing, he''s an available, caring person who does his job with passion — and you can really feel it. It was a real pleasure to have him by our side for our wedding. Thank you again — we recommend him without hesitation! A little extra: the lighting and spotlights were brilliant, the result is amazing. We recommend him 100%!', null, null, 'site', true, 420, '{mariages}'),
('Géraldine & William', null, null, 'mariage', 'Nous avons eu une super expérience avec Cédric. Son & DJ était parfait pour notre mariage, très professionnel et a maintenu la foule sutr la piste jusqu''à 4 heures du matin. Nous sommes extrêmement satisfaits du service fourni.', 'We had a great experience with Cédric. The sound & DJ were perfect for our wedding: very professional, and he kept the crowd on the dance floor until 4 am. We are extremely satisfied with the service provided.', null, null, 'site', true, 430, '{}');
